.app {
  min-height: 100vh;
  background: var(--g-color-base-background);
  color: var(--g-color-text-primary);
}

.app__header {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 24px;
  border-bottom: 1px solid var(--g-color-line-generic);
}

.app__nav {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.app__main {
  max-width: 760px;
  margin: 0 auto;
  padding: 32px 24px;
}

/* Страницы */

.page__lead {
  margin-top: 8px;
  color: var(--g-color-text-secondary);
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 16px;
  margin-top: 24px;
}

.card {
  padding: 16px;
}

.card__text {
  margin-top: 8px;
  color: var(--g-color-text-secondary);
}

/* Задачи */

.task-form {
  display: flex;
  gap: 8px;
  margin: 24px 0 16px;
}

.task-form__input {
  flex: 1;
}

.task-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin: 0;
  padding: 0;
