import { readFileSync } from 'node:fs';

const dom = new JSDOM('<!doctype html><html><body><div id="root"></div></body></html>', {
  url: 'http://localhost:4173/',
  pretendToBeVisual: true,
});
const { window } = dom;
const g = globalThis;
for (const key of ['window', 'document', 'navigator', 'localStorage', 'HTMLElement', 'Node', 'Event', 'KeyboardEvent', 'MouseEvent', 'getComputedStyle', 'requestAnimationFrame', 'cancelAnimationFrame']) {
  if (!(key in g) || key === 'window' || key === 'document') {
    Object.defineProperty(g, key, { value: window[key], configurable: true, writable: true });
  }
}
Object.defineProperty(g, 'navigator', { value: window.navigator, configurable: true });
window.matchMedia = () => ({ matches: false, addListener() {}, removeListener() {}, addEventListener() {}, removeEventListener() {} });
window.ResizeObserver = class { observe() {} unobserve() {} disconnect() {} };
g.IS_REACT_ACT_ENVIRONMENT = true;
g.ResizeObserver = window.ResizeObserver;
g.matchMedia = window.matchMedia;
g.SVGElement = window.SVGElement;
g.HTMLInputElement = window.HTMLInputElement;

const errors = [];
const origError = console.error;
console.error = (...args) => { errors.push(args.map(String).join(' ')); };

await import('/tmp/pwcheck/bundle.mjs');
const tick = (ms = 50) => new Promise((r) => setTimeout(r, ms));
await tick(200);

const $ = (sel) => window.document.querySelector(sel);
const $$ = (sel) => [...window.document.querySelectorAll(sel)];
const h1 = () => $('h1')?.textContent;
const bodyClass = () => window.document.body.className;
const clickEl = (el) => el.dispatchEvent(new window.MouseEvent('click', { bubbles: true, cancelable: true }));
const clickByText = (sel, text) => clickEl($$(sel).find((el) => el.textContent.trim() === text));
const results = [];
const check = (name, ok, extra = '') => results.push(`${ok ? 'PASS' : 'FAIL'} ${name}${extra ? ' — ' + extra : ''}`);

// 1. Initial state
check('initial page is Home', h1() === 'Добро пожаловать', h1());
check('initial theme is light (no dark class)', !/g-root_theme_dark/.test(bodyClass()), bodyClass());
check('initial body has g-root_theme_light', /g-root_theme_light/.test(bodyClass()), bodyClass());
check('active nav item has aria-current=page on Главная', $('a[aria-current="page"]')?.textContent === 'Главная');

// 2. Navigation via nav links (hash changes)
clickByText('nav a', 'Задачи');
await tick();
check('nav -> Задачи renders Tasks page', h1() === 'Задачи', `h1=${h1()} hash=${window.location.hash}`);
clickByText('nav a', 'О проекте');
await tick();
check('nav -> О проекте renders About page', h1() === 'О проекте', h1());
window.location.hash = '#/nonexistent';
await tick();
check('unknown hash falls back to Home', h1() === 'Добро пожаловать', h1());
window.location.hash = '#/tasks';
await tick();
check('direct hash #/tasks works', h1() === 'Задачи', h1());

// 3. Tasks: add, toggle, delete
const input = $('input[placeholder="Новая задача"]');
const setNative = (el, value) => {
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  setter.call(el, value);
  el.dispatchEvent(new window.Event('input', { bubbles: true }));
};
const submitBtn = $('button[type=submit]');
check('add button disabled while input empty', submitBtn.disabled === true);
setNative(input, '   Купить молоко  ');
await tick();
check('add button enabled after typing', $('button[type=submit]').disabled === false);
$('form.task-form').dispatchEvent(new window.Event('submit', { bubbles: true, cancelable: true }));
await tick();
const titles = $$('.task-list__item').map((el) => el.textContent.trim());
check('task added with trimmed title', titles.some((t) => t.startsWith('Купить молоко')), JSON.stringify(titles));
check('input cleared after add', $('input[placeholder="Новая задача"]').value === '');

const newItem = $$('.task-list__item').find((el) => el.textContent.includes('Купить молоко'));
const checkbox = newItem.querySelector('input[type=checkbox]');
checkbox.click();
await tick();
check('toggling checkbox marks task done', $$('.task-list__title--done').some((el) => el.textContent === 'Купить молоко'));
newItem.querySelector('.task-list__item button, button')?.click();
await tick();
const afterDelete = $$('.task-list__item').map((el) => el.textContent.trim());
check('delete removes the task', !afterDelete.some((t) => t.includes('Купить молоко')), JSON.stringify(afterDelete));

// 4. Theme toggle
window.location.hash = '#/';
await tick();
const themeSwitch = $$('input[type=checkbox]').find((el) => el.closest('label')?.textContent.includes('Тёмная тема'));
themeSwitch.click();
await tick();
check('toggle -> body gets dark theme class', /g-root_theme_dark/.test(bodyClass()), bodyClass());
check('toggle -> light class removed', !/g-root_theme_light/.test(bodyClass()), bodyClass());
check('toggle -> localStorage stores dark', window.localStorage.getItem('app-theme') === 'dark', String(window.localStorage.getItem('app-theme')));
check('switch reflects dark state', $$('input[type=checkbox]').find((el) => el.closest('label')?.textContent.includes('Тёмная тема')).checked === true);

// 5. Theme persists across "reload" (new App mount)
const rootEl = window.document.getElementById('root');
ReactDOM; // keep import
const { unmountComponentAtNode } = {};
const persisted = window.localStorage.getItem('app-theme');
check('dark theme stored for next visit', persisted === 'dark');

themeSwitch.click();
await tick();
check('toggle back -> light class restored', /g-root_theme_light/.test(bodyClass()), bodyClass());
check('toggle back -> stored light', window.localStorage.getItem('app-theme') === 'light');

// 6. Navigation keeps theme
themeSwitch.click();
await tick();
clickByText('nav a', 'Задачи');
await tick();
check('theme survives navigation', /g-root_theme_dark/.test(bodyClass()) && h1() === 'Задачи');

console.log(results.join('\n'));
const realErrors = errors.filter((e) => !/not wrapped in act|Warning: /.test(e));
console.log(`console.error calls: ${errors.length} (non-warning: ${realErrors.length})`);
if (realErrors.length) console.log(realErrors.slice(0, 5).join('\n---\n'));
if (errors.length && !realErrors.length) console.log('sample warning:', errors[0].slice(0, 300));
process.exit(results.some((r) => r.startsWith('FAIL')) ? 1 : 0);

